        EditText search=new EditText(this);search.setSingleLine();search.setTextColor(UiColors.color(getResources(),INK));search.setHintTextColor(UiColors.color(getResources(),MUTED));search.setHint(tab.equals("gear")?"搜索相机、镜头…":"搜索"+title(tab));search.setText(query);search.setBackground(surface(UiColors.color(getResources(),CARD)));search.setPadding(dp(14),dp(8),dp(14),dp(8));LinearLayout searchRow=new LinearLayout(this);searchRow.setGravity(Gravity.CENTER_VERTICAL);searchRow.setBackground(surface(UiColors.color(getResources(),CARD)));searchRow.addView(icon(0xe30c,"搜索",20,UiColors.color(getResources(),MUTED)),new LinearLayout.LayoutParams(dp(36),dp(44)));search.setBackgroundColor(Color.TRANSPARENT);search.setMinimumHeight(dp(44));searchRow.addView(search,new LinearLayout.LayoutParams(0,-2,1));if(tab.equals("stock")){Button filter=button("",false,()->new AlertDialog.Builder(this).setTitle("库存筛选").setSingleChoiceItems(new String[]{"当前库存","已归档库存"},archived?1:0,(d,w)->{archived=w==1;location="";d.dismiss();render();}).setNegativeButton("取消",null).show());filter.setTypeface(android.graphics.Typeface.createFromAsset(getAssets(),"fonts/Phosphor.ttf"));filter.setText(String.valueOf((char)0xe434));filter.setTextSize(21);filter.setContentDescription(archived?"库存筛选，已归档库存":"库存筛选，当前库存");filter.setBackgroundColor(Color.TRANSPARENT);searchRow.addView(filter,new LinearLayout.LayoutParams(dp(44),dp(44)));}root.addView(searchRow);
