        ScrollView scroll=new ScrollView(this);listPage=scroll;scroll.post(()->scroll.scrollTo(0,listScroll));content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));show();search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){query=s.toString();show();}public void afterTextChanged(android.text.Editable s){}});if(mainProjects())root.addView(MainNavigation.tabs(this,"home",this::exitMain));
