    private void renderLibraryPage(){root=column();root.setBackgroundColor(getColor(R.color.ui_background));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();root.addView(LibraryUi.header(this,tab.equals("gear")?"我的器材":"胶片库存",this::finish,LibraryUi.icon(this,0xe3d4,tab.equals("gear")?"添加器材":"添加库存",()->{formDraft=null;if(tab.equals("stock"))batchForm(null);else new AlertDialog.Builder(this).setTitle("添加器材").setItems(new String[]{"相机","镜头"},(d,w)->entryForm(null,w==0?"camera":"lens")).show();})));
        LinearLayout pane=column();pane.setPadding(dp(16),0,dp(16),0);root.addView(pane,new LinearLayout.LayoutParams(-1,0,1));LinearLayout searchRow=new LinearLayout(this);searchRow.setGravity(Gravity.CENTER_VERTICAL);searchRow.setBackground(surface(getColor(R.color.ui_card)));EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setTextColor(getColor(R.color.ui_ink));search.setHintTextColor(getColor(R.color.ui_muted));search.setHint(tab.equals("gear")?"搜索相机、镜头或昵称…":"搜索片种、存放位置…");search.setBackgroundColor(Color.TRANSPARENT);search.setPadding(dp(12),0,dp(8),0);search.setText(query);searchRow.addView(search,new LinearLayout.LayoutParams(0,dp(44),1));searchRow.addView(LibraryUi.icon(this,0xe434,tab.equals("gear")?"筛选器材":"筛选库存",this::libraryFilters),new LinearLayout.LayoutParams(dp(44),dp(44)));pane.addView(searchRow);
        String chips=(archived?"已归档 · ":"")+(favoriteFilter&&tab.equals("gear")?"仅收藏 · ":"")+(!location.isEmpty()?location+" · ":"")+(!stockAttention.isEmpty()?(stockAttention.equals("low")?"库存偏低":"临近或已到期"):"");if(!chips.isEmpty()){Button status=LibraryUi.action(this,chips.replaceAll(" · $",""),false,this::libraryFilters);status.setBackgroundColor(Color.TRANSPARENT);pane.addView(status);}
        if(tab.equals("gear")){if(gearFilter.equals("favorites")){favoriteFilter=true;gearFilter="all";}String[] keys={"all","camera","lens"};int selected=Arrays.asList(keys).indexOf(gearFilter);pane.addView(LibraryUi.tabs(this,new String[]{"全部","相机","镜头"},Math.max(0,selected),n->{gearFilter=keys[n];listScroll=0;render();}));}
        ScrollView scroll=new ScrollView(this);listPage=scroll;scroll.setTag("catalog-list");scroll.setVerticalScrollBarEnabled(false);scroll.setFillViewport(false);content=column();content.setPadding(0,dp(8),0,dp(24));scroll.addView(content);pane.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));show();scroll.post(()->scroll.scrollTo(0,listScroll));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence value,int a,int b,int c){query=value.toString();listScroll=0;show();}public void afterTextChanged(android.text.Editable e){}});
    }
    private void libraryFilters(){LinearLayout body=form();CheckBox archive=new CheckBox(this);archive.setText(tab.equals("gear")?"查看已归档器材":"查看已归档库存");archive.setChecked(archived);body.addView(archive);CheckBox favorite=new CheckBox(this);favorite.setText("仅收藏的器材");favorite.setChecked(favoriteFilter);if(tab.equals("gear"))body.addView(favorite);ArrayList<String> locations=new ArrayList<>();locations.add("全部存放位置");TreeSet<String> places=new TreeSet<>();for(CatalogStore.Batch b:catalog.batches(false))if(!b.location.isEmpty())places.add(b.location);locations.addAll(places);Spinner place=new Spinner(this),attention=new Spinner(this);place.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,locations));place.setSelection(location.isEmpty()?0:Math.max(0,locations.indexOf(location)));attention.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"全部状态","库存偏低","临近或已到期"}));attention.setSelection(stockAttention.equals("low")?1:stockAttention.equals("soon")?2:0);if(tab.equals("stock")){body.addView(label("存放位置",12,getColor(R.color.ui_muted)));body.addView(place,new LinearLayout.LayoutParams(-1,dp(48)));body.addView(label("库存状态",12,getColor(R.color.ui_muted)));body.addView(attention,new LinearLayout.LayoutParams(-1,dp(48)));}final Dialog[] sheet={null};LinearLayout foot=new LinearLayout(this);foot.addView(button("重置",false,()->{archive.setChecked(false);favorite.setChecked(false);place.setSelection(0);attention.setSelection(0);}),new LinearLayout.LayoutParams(0,-2,1));foot.addView(button("应用筛选",true,()->{archived=archive.isChecked();favoriteFilter=favorite.isChecked();location=place.getSelectedItemPosition()==0?"":place.getSelectedItem().toString();stockAttention=new String[]{"","low","soon"}[attention.getSelectedItemPosition()];listScroll=0;sheet[0].dismiss();render();}),new LinearLayout.LayoutParams(0,-2,1));sheet[0]=librarySheet=LibraryUi.sheet(this,"筛选"+(tab.equals("gear")?"器材":"库存"),body,foot);}
    private void locationChips(LinearLayout container){
        SortedMap<String,Long> counts=new TreeMap<>();long total=0;for(CatalogStore.Batch b:catalog.batches(archived)){total+=b.quantity;if(!b.location.isEmpty())counts.put(b.location,counts.getOrDefault(b.location,0L)+b.quantity);}
        HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);LinkedHashMap<String,Long> choices=new LinkedHashMap<>();choices.put("",total);choices.putAll(counts);Button selected=null;
        if(!location.isEmpty()&&!counts.containsKey(location))location="";
        for(Map.Entry<String,Long> entry:choices.entrySet()){String key=entry.getKey();Button chip=button((key.isEmpty()?"全部":key)+" "+entry.getValue(),false,()->{location=key;render();});boolean checked=location.equals(key);chip.setSelected(checked);chip.setTextColor(checked?UiColors.onAccent(getResources()):UiColors.color(getResources(),MUTED));GradientDrawable bg=surface(checked?UiColors.color(getResources(),INK):UiColors.color(getResources(),CARD));bg.setCornerRadius(dp(24));chip.setBackground(bg);chip.setMinHeight(0);chip.setMinimumHeight(0);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-2,dp(36));size.setMargins(0,dp(8),dp(8),dp(4));row.addView(chip,size);if(checked)selected=chip;}
        scroll.addView(row);container.addView(scroll,new LinearLayout.LayoutParams(0,-2,1));Button target=selected;if(target!=null)scroll.post(()->scroll.scrollTo(Math.max(0,target.getLeft()-dp(20)),0));
    }
    private void show(){content.removeAllViews();String term=query.trim().toLowerCase(Locale.ROOT);int shown=0;
        if(tab.equals("stock")){
            ArrayList<CatalogStore.Batch> batches=new ArrayList<>();for(CatalogStore.Batch b:catalog.batches(archived))if((location.isEmpty()||location.equals(b.location))&&(stockAttention.isEmpty()||stockAttention.equals("low")&&b.quantity<b.threshold||stockAttention.equals("soon")&&CatalogStore.expiring(b,LocalDate.now()))&&(b.stock+" "+b.notes+" "+b.location).toLowerCase(Locale.ROOT).contains(term))batches.add(b);
            Comparator<CatalogStore.Batch> order=Comparator.comparing((CatalogStore.Batch b)->b.stock,String.CASE_INSENSITIVE_ORDER).thenComparing(b->b.id);
            if(stockSort.equals("expiry"))order=Comparator.comparing((CatalogStore.Batch b)->b.expiry.isEmpty()?"9999-12-31":b.expiry).thenComparing(order);
            else if(stockSort.equals("quantity"))order=Comparator.comparingInt((CatalogStore.Batch b)->b.quantity).thenComparing(order);
            batches.sort(order);if(catalog.batches(archived).isEmpty()){content.addView(label(archived?"还没有已归档库存":"还没有胶片库存",20,getColor(R.color.ui_ink)));content.addView(label("先添加一批胶片，记录数量和存放位置。",13,getColor(R.color.ui_muted)));content.addView(button(archived?"查看当前库存":"添加库存",true,()->{if(archived){archived=false;render();}else{formDraft=null;batchForm(null);}}));return;}if(!batches.isEmpty())stockSummary(batches);
            LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(label(batches.size()+" 个批次",12,UiColors.color(getResources(),MUTED)),new LinearLayout.LayoutParams(0,-2,1));heading.addView(button((stockSort.equals("expiry")?"到期日期":stockSort.equals("quantity")?"数量":"名称")+" ▾",false,()->new AlertDialog.Builder(this).setTitle("库存排序").setItems(new String[]{"名称","到期日期（近到远）","数量（少到多）"},(d,w)->{stockSort=new String[]{"name","expiry","quantity"}[w];show();}).show()));content.addView(heading);
            LinkedHashMap<String,ArrayList<CatalogStore.Batch>> groups=new LinkedHashMap<>();for(CatalogStore.Batch b:batches)groups.computeIfAbsent(b.format,k->new ArrayList<>()).add(b);
            for(Map.Entry<String,ArrayList<CatalogStore.Batch>> group:groups.entrySet()){
                long count=0;for(CatalogStore.Batch b:group.getValue())count+=b.quantity;
                content.addView(label(group.getKey()+"    ·    "+count+" 卷",12,UiColors.color(getResources(),MUTED)));LinearLayout card=column();GradientDrawable bg=surface(UiColors.color(getResources(),CARD));card.setBackground(bg);content.addView(card);
                for(CatalogStore.Batch b:group.getValue()){
                    boolean low=b.quantity<b.threshold;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(12),dp(12),dp(12));
                    TextView box=icon(0xe390,"库存批次",24,low?0xffdbab4c:UiColors.color(getResources(),MUTED));box.setBackground(surface(low?UiColors.color(getResources(),0xff40311c):UiColors.color(getResources(),0xff3c3027)));if(!ArtworkLinks.thumbnail(this,logs,"batch",b.id,row,48))row.addView(box,new LinearLayout.LayoutParams(dp(40),dp(40)));
                    LinearLayout description=column();description.addView(label(b.stock,17,UiColors.color(getResources(),INK)));description.addView(label("ISO "+b.iso+" · "+b.capacity+" 张"+(b.location.isEmpty()?"":" · "+b.location),12,UiColors.color(getResources(),MUTED)));if(!b.expiry.isEmpty())description.addView(label((LocalDate.parse(b.expiry).isBefore(LocalDate.now())?"已到期 ":"到期 ")+b.expiry,12,UiColors.color(getResources(),MUTED)));row.addView(description,new LinearLayout.LayoutParams(0,-2,1));TextView quantity=label("×"+b.quantity,15,low?0xffdbab4c:UiColors.color(getResources(),MUTED));row.addView(quantity);row.addView(label("›",20,UiColors.color(getResources(),MUTED)));row.setOnClickListener(v->batchActions(b));row.setFocusable(true);row.setContentDescription(b.stock+"，库存"+b.quantity+"卷，"+b.format+(low?"，库存偏低":""));card.addView(row);shown++;
                    if(b!=group.getValue().get(group.getValue().size()-1)){View divider=new View(this);divider.setBackgroundColor(UiColors.color(getResources(),0xff554237));LinearLayout.LayoutParams line=new LinearLayout.LayoutParams(-1,dp(1));line.leftMargin=dp(64);card.addView(divider,line);}
                }
            }
        }else if(tab.equals("gear")){showGear(term);return;}else if(tab.equals("project")){showProjects(term);return;}else for(CatalogStore.Entry entry:catalog.entries(tab,archived)){if(!(entry.name+" "+entry.cameraModel+" "+entry.notes).toLowerCase(Locale.ROOT).contains(term))continue;Button b=button(entry.name+(entry.format.isEmpty()?"":" · "+entry.format),false,()->entryActions(entry));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);content.addView(b,p);shown++;}
        if(shown==0){content.addView(label("没有匹配的"+title(tab),17,getColor(R.color.ui_ink)));content.addView(button("清除搜索与筛选",false,()->{query="";location="";stockAttention="";render();}));}
    }
    private ArrayList<CatalogStore.Entry> gearEntries(){ArrayList<CatalogStore.Entry> entries=catalog.entries("camera",archived);entries.addAll(catalog.entries("lens",archived));return entries;}
    private void gearChips(){ArrayList<CatalogStore.Entry> all=gearEntries();int favorites=0,cameras=0;for(CatalogStore.Entry e:all){if(e.favorite)favorites++;if(e.kind.equals("camera"))cameras++;}HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);String[] keys={"all","favorites","camera","lens","archive"},names={"全部 "+all.size(),"收藏 "+favorites,"相机 "+cameras,"镜头 "+(all.size()-cameras),archived?"已归档 ✓":"当前 ▾"};for(int i=0;i<keys.length;i++){String key=keys[i];Button chip=button(names[i],false,()->{if(key.equals("archive"))archived=!archived;else gearFilter=key;render();});boolean selected=gearFilter.equals(key);chip.setSelected(selected);chip.setTextColor(selected?UiColors.onAccent(getResources()):UiColors.color(getResources(),MUTED));GradientDrawable bg=surface(selected?UiColors.color(getResources(),INK):UiColors.color(getResources(),CARD));bg.setCornerRadius(dp(24));chip.setBackground(bg);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-2,dp(36));size.setMargins(0,dp(6),dp(6),dp(6));row.addView(chip,size);if(selected)scroll.post(()->scroll.scrollTo(Math.max(0,chip.getLeft()-dp(16)),0));}scroll.addView(row);root.addView(scroll);}
    private LinearLayout gearCard(){LinearLayout card=column();GradientDrawable bg=surface(UiColors.color(getResources(),0xff2c211a));card.setBackground(bg);content.addView(card);return card;}
    private void gearDivider(LinearLayout card){if(card.getChildCount()==0)return;View line=new View(this);line.setBackgroundColor(UiColors.color(getResources(),0xff49372b));LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(-1,dp(1));size.leftMargin=dp(64);card.addView(line,size);}
