        dialog.getButton(-2).setOnClickListener(v->close.run());dialog.getButton(-1).setOnClickListener(v->{if(text(name).isEmpty()){name.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);return;}try{catalog.saveProject(entry==null?"":entry.id,text(name),text(description),formDraft.getString("projectColor",""));discard.run();render();}catch(Exception invalid){toast(invalid.getMessage());}});
