        if(!archived){ArrayList<LogStore.Roll> unassigned=new ArrayList<>();for(LogStore.Roll roll:logs.rolls()){CatalogStore.Detail detail=catalog.detail(roll.id);if(detail==null||detail.project.isEmpty())unassigned.add(roll);}content.addView(button("未归入项目 · "+unassigned.size()+" 卷",false,()->chooseProjectRolls("未归入项目",unassigned)));}
