    static int projectStripFilled(long taken,long total){if(taken<=0||total<=0)return 0;if(taken>=total)return 18;return (int)Math.max(1,Math.min(17,Math.round(taken/(double)total*18)));}
    static long projectStart(CatalogStore.Entry project){return project.startedAt==null?project.createdAt:project.startedAt;}
    static long projectDays(long created,Long completed,long now){return Math.max(0,java.time.Duration.between(java.time.Instant.ofEpochMilli(created),java.time.Instant.ofEpochMilli(completed==null?now:completed)).toDays());}
    private static String projectDate(long time){return java.time.Instant.ofEpochMilli(time).atZone(java.time.ZoneId.systemDefault()).toLocalDate().format(java.time.format.DateTimeFormatter.ofPattern("M月d日"));}
    static String projectSince(long created,long now,java.time.ZoneId zone){
        LocalDate date=java.time.Instant.ofEpochMilli(created).atZone(zone).toLocalDate(),today=java.time.Instant.ofEpochMilli(now).atZone(zone).toLocalDate();
        long days=java.time.Duration.between(date.atStartOfDay(zone),today.atStartOfDay(zone)).toHours()/24;
        return days<=0?"从今天起":days==1?"从昨天起":"自 "+date.format(java.time.format.DateTimeFormatter.ofPattern("M月d日"))+" 起";
    }
    private View projectStrip(long taken,long total){
        final int filled=projectStripFilled(taken,total);
        View view=new View(this){final android.graphics.Paint paint=new android.graphics.Paint(3);
            @Override protected void onDraw(android.graphics.Canvas canvas){super.onDraw(canvas);float width=Math.min(getWidth(),dp(220)),gap=dp(2),cell=Math.max(0,(width-gap*17)/18);for(int i=0;i<18;i++){paint.setColor(i<filled?UiColors.color(getResources(),INK):UiColors.color(getResources(),0xff574940));canvas.drawRoundRect(i*(cell+gap),0,i*(cell+gap)+cell,getHeight(),dp(1),dp(1),paint);}}
        };
        // shortcut: Original role colors/gradient remain approximate pending same-condition Android comparison.
        view.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);return view;
    }
