        Button create=button("",false,()->{projectSheet="";dialog.dismiss();startActivity(new Intent(this,MainActivity.class).putExtra("new_roll",true).putExtra("new_roll_project",project.id).putExtra("return_to_project",true).putExtra("widget_workspace",Workspace.identity(getBaseContext())));});create.setText(projectChoiceLabel(0xe792,"新建胶卷\n打开新建胶卷向导"));create.setContentDescription("新建胶卷，打开新建胶卷向导");body.addView(create);
