    private void pickFreeProjectRoll(CatalogStore.Entry project){
        projectSheet="existing";ArrayList<LogStore.Roll> free=new ArrayList<>();for(LogStore.Roll roll:logs.rolls()){CatalogStore.Detail detail=catalog.detail(roll.id);if(detail==null||detail.project.isEmpty())free.add(roll);}LinearLayout title=column();title.setPadding(dp(16),dp(8),dp(16),0);title.addView(label("添加已有胶卷",20,UiColors.color(getResources(),INK)));title.addView(label("选择一卷未归入项目的胶卷",13,UiColors.color(getResources(),MUTED)));AlertDialog.Builder builder=new AlertDialog.Builder(this).setCustomTitle(title).setNegativeButton("取消",(d,w)->cancelProjectSheet());
        if(free.isEmpty())builder.setMessage("所有胶卷都已归入项目");else{String[] labels=new String[free.size()];for(int i=0;i<labels.length;i++){LogStore.Roll roll=free.get(i);labels[i]=roll.name+" · "+roll.stock+"\n"+roll.count+"/"+roll.capacity+" 张";}builder.setItems(labels,(dialog,index)->{try{catalog.assignFreeRoll(free.get(index).id,project.id);root.performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);projectSheet="";toast("胶卷已归入项目");render();}catch(Exception stale){projectSheet="";toast(stale.getMessage());render();}});}
        AlertDialog dialog=builder.create();dialog.setOnCancelListener(d->cancelProjectSheet());dialog.show();dialog.getWindow().setGravity(Gravity.BOTTOM);dialog.getWindow().setLayout(-1,-2);
    }
    private void chooseProjectRolls(String title,ArrayList<LogStore.Roll> rolls){if(rolls.isEmpty()){toast("此项目中没有胶卷");return;}String[] names=new String[rolls.size()];for(int i=0;i<names.length;i++)names[i]=rolls.get(i).name+(rolls.get(i).archived?"（已归档）":"");new AlertDialog.Builder(this).setTitle(title).setItems(names,(d,w)->{setResult(RESULT_OK,new Intent().putExtra("roll",rolls.get(w).id));finish();}).show();}
    private void projectActions(CatalogStore.Entry entry){String[] actions=entry.archived?new String[]{"重新启用","编辑","删除"}:new String[]{entry.completed?"重新启用":"标记为已完成","编辑","归档","删除"};new AlertDialog.Builder(this).setTitle(entry.name).setItems(actions,(d,w)->{try{formDraft=null;if(w==0){catalog.completeProject(entry.id,entry.archived?false:!entry.completed);render();}else if(w==1)projectForm(entry);else if(!entry.archived&&w==2){catalog.archiveEntry(entry.id,"project",true);render();}else new AlertDialog.Builder(this).setTitle("删除“"+entry.name+"”？").setMessage("胶卷不会被删除。").setNegativeButton("取消",null).setPositiveButton("删除",(confirm,which)->{try{catalog.deleteProject(entry.id);if(selectedProject.equals(entry.id)){selectedProject="";projectPage=null;}toast("项目已删除");render();}catch(Exception invalid){toast("无法更新项目");}}).show();}catch(Exception invalid){toast("无法更新项目："+invalid.getMessage());}}).show();}
    private void entryForm(CatalogStore.Entry entry,String kind){if(kind.equals("camera")){begin(kind,entry==null?"":entry.id);Bundle cameraState=formDraft.getBundle("cameraEditor");if(cameraState==null){cameraState=new Bundle();formDraft.putBundle("cameraEditor",cameraState);}CameraEditor.show(this,logs,cameraState,entry,id->{formDraft=null;fields.clear();render();},()->{formDraft=null;fields.clear();});return;}if(kind.equals("project")){projectForm(entry);return;}begin(kind,entry==null?"":entry.id);LinearLayout body=form();EditText name=input(body,"名称",entry==null?"":entry.name,InputType.TYPE_CLASS_TEXT),format=kind.equals("project")?null:input(body,kind.equals("camera")?"胶片规格（可选，如35 mm或120）":"适用规格（可选）",entry==null?"":entry.format,InputType.TYPE_CLASS_TEXT),notes=input(body,"备注",entry==null?"":entry.notes,InputType.TYPE_CLASS_TEXT),condition=kind.equals("project")?null:input(body,"成色（可选）",entry==null?"":entry.condition,InputType.TYPE_CLASS_TEXT);Runnable chooseModel=()->OriginalCatalog.chooseCamera(this,"",formDraft,camera->{name.setText(camera.name);format.setText(camera.filmFormat());});if(kind.equals("camera")){Button model=button("从机型目录选择  ›",false,chooseModel);body.addView(model,0);}CheckBox favorite=new CheckBox(this);favorite.setText("收藏");favorite.setTextColor(UiColors.color(getResources(),INK));favorite.setChecked(formDraft.getBoolean("favorite",entry!=null&&entry.favorite));favorite.setOnCheckedChangeListener((v,checked)->formDraft.putBoolean("favorite",checked));if(!kind.equals("project"))body.addView(favorite);dialog((entry==null?"新建":"编辑")+title(kind),body,"保存",()->{catalog.saveEntry(entry==null?"":entry.id,kind,name.getText().toString(),format==null?"":text(format),text(notes),condition==null?"":text(condition),favorite.isChecked());render();});if(kind.equals("camera")&&formDraft.getBoolean("cameraCatalogOpen",false))chooseModel.run();}
    private String text(EditText input){return input.getText().toString().trim();}
    private void expiryText(EditText field,String date){field.setTag(date);formDraft.putString("expiryDate",date);try{field.setText(date.isEmpty()?"":java.time.YearMonth.from(LocalDate.parse(date)).format(java.time.format.DateTimeFormatter.ofPattern("yyyy年MM月")));}catch(Exception invalid){field.setText(date);}}
    private EditText expiryField(LinearLayout body,String original){EditText field=input(body,"到期月份（可选，点选或清除）",original,1);String date=formDraft.getString("expiryDate",field.getText().toString());expiryText(field,date);field.setFocusable(false);field.setCursorVisible(false);field.setOnClickListener(v->chooseExpiry(field));if(formDraft.getBoolean("expiryPicker",false))field.post(()->chooseExpiry(field));return field;}
    private void clearExpiryPicker(){formDraft.remove("expiryPicker");formDraft.remove("expiryYear");formDraft.remove("expiryMonth");}
    private void chooseExpiry(EditText field){
        java.time.YearMonth initial=java.time.YearMonth.now();try{initial=java.time.YearMonth.from(LocalDate.parse((String)field.getTag()));}catch(Exception ignored){}
        NumberPicker year=new NumberPicker(this),month=new NumberPicker(this);year.setMinValue(1);year.setMaxValue(9999);month.setMinValue(1);month.setMaxValue(12);year.setValue(formDraft.getInt("expiryYear",Math.max(1,Math.min(9999,initial.getYear()))));month.setValue(formDraft.getInt("expiryMonth",initial.getMonthValue()));year.setWrapSelectorWheel(false);month.setWrapSelectorWheel(true);year.setDescendantFocusability(NumberPicker.FOCUS_BLOCK_DESCENDANTS);month.setDescendantFocusability(NumberPicker.FOCUS_BLOCK_DESCENDANTS);year.setContentDescription("到期年份");month.setContentDescription("到期月份");
        formDraft.putBoolean("expiryPicker",true);formDraft.putInt("expiryYear",year.getValue());formDraft.putInt("expiryMonth",month.getValue());year.setOnValueChangedListener((picker,old,next)->formDraft.putInt("expiryYear",next));month.setOnValueChangedListener((picker,old,next)->formDraft.putInt("expiryMonth",next));LinearLayout row=new LinearLayout(this);row.setPadding(dp(24),dp(8),dp(24),dp(8));row.addView(year,new LinearLayout.LayoutParams(0,dp(160),1));row.addView(month,new LinearLayout.LayoutParams(0,dp(160),1));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("到期月份 · 年 / 月").setView(row).setNegativeButton("取消",(d,w)->clearExpiryPicker()).setNeutralButton("清除",(d,w)->{expiryText(field,"");clearExpiryPicker();}).setPositiveButton("确定",(d,w)->{expiryText(field,CatalogStore.expiryMonth(year.getValue(),month.getValue()));clearExpiryPicker();}).create();dialog.setOnCancelListener(d->clearExpiryPicker());dialog.show();dialog.getButton(-3).setTextColor(UiColors.color(getResources(),0xffef8994));
    }
    private void batchForm(CatalogStore.Batch old){begin("stock",old==null?"":old.id);if(!formDraft.containsKey("expected"))formDraft.putInt("expected",old==null?0:old.quantity);LinearLayout body=form();
        body.addView(button("从片种库选择  ›",false,()->startActivityForResult(new Intent(this,StockLibraryActivity.class).putExtra("select",true).putExtra("format",fields.size()>1?fields.get(1).getText().toString():""),77)));EditText stock=input(body,"胶片名称",old==null?"":old.stock,1),format=input(body,"规格",old==null?"35 mm":old.format,1),iso=input(body,"ISO",old==null?"400":""+old.iso,2),capacity=input(body,"每卷曝光张数",old==null?"36":""+old.capacity,2),quantity=input(body,"库存卷数",old==null?"1":""+old.quantity,2),threshold=input(body,"低库存提醒阈值",old==null?"2":""+old.threshold,2),location=input(body,"存放位置",old==null?"":old.location,1),temperature=input(body,"存放温度",old==null?"":old.temperature,1),expiry=expiryField(body,old==null?"":old.expiry),purchase=input(body,"购买日期（可选，YYYY-MM-DD）",old==null?"":old.purchaseDate,1),price=input(body,"每卷成本（可选）",old==null?"":old.price,InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL),currency=input(body,"币种（可选，如 CNY）",old==null?"":old.currency,1),notes=input(body,"备注",old==null?"":old.notes,1);
        dialog(old==null?"添加库存批次":"编辑库存批次",body,"保存库存",()->{CatalogStore.Batch b=new CatalogStore.Batch();b.id=old==null?"":old.id;b.stockId=formDraft.containsKey("stockId")?formDraft.getString("stockId"):null;b.stock=text(stock);b.format=text(format);b.iso=Integer.parseInt(text(iso));b.capacity=Integer.parseInt(text(capacity));b.quantity=Integer.parseInt(text(quantity));b.threshold=Integer.parseInt(text(threshold));b.location=text(location);b.temperature=text(temperature);b.expiry=(String)expiry.getTag();b.purchaseDate=text(purchase);b.price=text(price);b.currency=text(currency).toUpperCase(Locale.ROOT);b.notes=text(notes);catalog.saveBatch(b,formDraft.getInt("expected"));render();});
    }
    private void batchActions(CatalogStore.Batch b){LinearLayout body=form();final Dialog[] sheet={null};LibraryUi.fact(this,body,"库存",b.quantity+" 卷");LibraryUi.fact(this,body,"规格",b.format+" · ISO "+b.iso+" · "+b.capacity+" 张");if(!b.location.isEmpty())LibraryUi.fact(this,body,"存放位置",b.location);if(!b.expiry.isEmpty())LibraryUi.fact(this,body,"有效期",b.expiry);if(!b.price.isEmpty())LibraryUi.fact(this,body,"每卷价格",b.price+" "+b.currency);if(!b.notes.isEmpty())body.addView(label(b.notes,13,getColor(R.color.ui_muted)));body.addView(button("库存历史 ›",false,()->new AlertDialog.Builder(this).setTitle("库存历史").setMessage(catalog.history(b.id)).setPositiveButton("关闭",null).show()));body.addView(button("编辑批次 ›",false,()->{sheet[0].dismiss();formDraft=null;batchForm(b);}));body.addView(button(b.archived?"恢复批次":"归档批次",false,()->{catalog.archiveBatch(b.id,!b.archived);sheet[0].dismiss();render();}));Button load=button(b.quantity==0?"库存已用完":"从这批库存装卷",true,()->{sheet[0].dismiss();formDraft=null;load(b.id);});load.setEnabled(b.quantity>0&&!b.archived);sheet[0]=librarySheet=LibraryUi.sheet(this,b.stock,body,load);}
    private void choose(String kind,String chosen,java.util.function.Consumer<String> result){ArrayList<CatalogStore.Entry> entries=catalog.entries(kind,false);String[] names=new String[entries.size()+1];names[0]="不选择";int checked=0;for(int i=0;i<entries.size();i++){names[i+1]=entries.get(i).name;if(entries.get(i).id.equals(chosen))checked=i+1;}new AlertDialog.Builder(this).setTitle("选择"+title(kind)).setSingleChoiceItems(names,checked,(d,w)->{result.accept(w==0?"":entries.get(w-1).id);d.dismiss();}).setNegativeButton("取消",null).show();}
    private void load(String batchId){CatalogStore.Batch b=catalog.batch(batchId);begin("load",batchId);if(!formDraft.containsKey("request"))formDraft.putString("request",UUID.randomUUID().toString());LinearLayout body=form();body.addView(label(b.stock+" · "+b.format+" · 剩余 "+b.quantity+" 卷",16,UiColors.color(getResources(),INK)));body.addView(label("确认保存时扣减1卷；取消不扣库存。",13,UiColors.color(getResources(),MUTED)));EditText name=input(body,"胶卷名称（可选）","",1);
        Button camera=button("选择相机（可选）",false,()->{}),project=button("选择项目（可选）",false,()->{});body.addView(camera);body.addView(project);
        for(String kind:new String[]{"camera","project"}){Button control=kind.equals("camera")?camera:project;String selected=formDraft.getString(kind,"");if(!selected.isEmpty())control.setText(catalog.entry(selected,kind).name);control.setOnClickListener(v->choose(kind,formDraft.getString(kind,""),id->{formDraft.putString(kind,id);control.setText(id.isEmpty()?"选择"+title(kind)+"（可选）":catalog.entry(id,kind).name);}));}
        dialog("从库存装卷",body,"保存胶卷",()->{String roll=catalog.load(batchId,formDraft.getString("request"),text(name),formDraft.getString("camera",""),formDraft.getString("project",""));setResult(RESULT_OK,new Intent().putExtra("roll",roll).putExtra("created_roll",true));finish();});
    }
    private void entryActions(CatalogStore.Entry e){if(e.kind.equals("project")){projectActions(e);return;}ArrayList<String> actions=new ArrayList<>(Arrays.asList("编辑",e.archived?"恢复":"归档"));boolean gear=!e.kind.equals("project");if(gear)actions.add(e.favorite?"取消收藏":"收藏");if(e.kind.equals("project")||e.kind.equals("camera"))actions.add("查看关联胶卷");new AlertDialog.Builder(this).setTitle(e.name).setItems(actions.toArray(new String[0]),(d,w)->{formDraft=null;if(w==0)entryForm(e,e.kind);else if(w==1){catalog.archiveEntry(e.id,e.kind,!e.archived);render();}else if(gear&&w==2){catalog.favorite(e.id,e.kind,!e.favorite);render();}else linkedRolls(e);}).show();}
    private void linkedRolls(CatalogStore.Entry entry){ArrayList<LogStore.Roll> linked=new ArrayList<>();for(LogStore.Roll roll:logs.rolls()){CatalogStore.Detail d=catalog.detail(roll.id);if(d!=null&&(entry.kind.equals("project")?d.project:d.camera).equals(entry.id))linked.add(roll);}String[] names=new String[linked.size()];for(int i=0;i<names.length;i++)names[i]=linked.get(i).name+(linked.get(i).archived?"（已归档）":"");if(names.length==0){toast("暂无关联胶卷");return;}new AlertDialog.Builder(this).setTitle(entry.name).setItems(names,(d,w)->{if(entry.kind.equals("camera"))openRoll(linked.get(w));else{setResult(RESULT_OK,new Intent().putExtra("roll",linked.get(w).id));finish();}}).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==78){if(result==RESULT_OK&&data!=null&&!artworkOwner.isEmpty())try{ArtworkLinks.set(this,logs,"batch",artworkOwner,data.getStringExtra("stock"));render();}catch(Exception error){toast(error.getMessage());}artworkOwner="";return;}if(request==77&&result==RESULT_OK&&data!=null&&formDraft!=null&&"stock".equals(formDraft.getString("type"))&&fields.size()>2)try{FilmStockStore.Stock stock=new FilmStockStore(logs).choose(this,data.getStringExtra("stock"),fields.get(1).getText().toString());formDraft.putString("stockId",stock.id);fields.get(0).setText(stock.title());fields.get(2).setText(String.valueOf(stock.iso==0?data.getIntExtra("stock_iso",0):stock.iso));}catch(Exception error){toast(error.getMessage());}}
    @Override protected void onSaveInstanceState(Bundle out){if(formDraft!=null)for(int i=0;i<fields.size();i++)formDraft.putString("field"+i,fields.get(i).getText().toString());if(projectPage!=null&&!selectedProject.isEmpty())projectScroll=projectPage.getScrollY();if(listPage!=null)listScroll=listPage.getScrollY();out.putString("selectedProject",selectedProject);out.putString("projectSheet",projectSheet);out.putInt("projectScroll",projectScroll);out.putInt("listScroll",listScroll);out.putString("artworkOwner",artworkOwner);out.putBundle("form",formDraft);out.putString("tab",tab);out.putString("gearFilter",gearFilter);out.putString("query",query);out.putString("location",location);out.putBoolean("archived",archived);out.putString("stockSort",stockSort);out.putBoolean("favoriteFilter",favoriteFilter);out.putString("stockAttention",stockAttention);out.putString("dismissedAttention",dismissedAttention);out.putString("mainProjectState",mainProjectState);super.onSaveInstanceState(out);}
